<?php
header('Access-Control-Allow-Origin: *');header('Access-Control-Allow-Methods: GET, OPTIONS');header('Access-Control-Allow-Headers: Content-Type, Authorization');header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']==='OPTIONS'){exit;}
require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/rut.php';require_once __DIR__.'/../includes/urgencias.php';
try{$pdo=getDB();asegurarTablaUrgencias($pdo);$rut=normalizarRut(trim((string)($_GET['rut']??'')));$q=$pdo->prepare('SELECT u.id,u.motivo,u.estado,u.observacion_recepcion,u.fecha_solicitud,u.fecha_actualizacion,m.nombre mascota FROM urgencias u JOIN duenos d ON d.id=u.dueno_id JOIN mascotas m ON m.id=u.mascota_id WHERE d.rut=:rut ORDER BY u.fecha_solicitud DESC LIMIT 30');$q->execute([':rut'=>$rut]);echo json_encode(['success'=>true,'urgencias'=>$q->fetchAll()]);}catch(Throwable $e){error_log('API mis urgencias: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Error del servidor']);}
